import { useEffect, useMemo, useState } from 'react'
import { activities as seedActivities, courses, emptyActivity, emptyStudent, resources, rubric, students as seedStudents } from './data/classroomData'
import type { Activity, RubricCriterion, Student, ViewKey } from './types'
import { Icon, ProgressBar, SectionLabel, StatusPill } from './components/SharedUI'

const navItems: { key: Exclude<ViewKey, 'home'>; label: string; icon: string }[] = [
  { key: 'overview', label: 'Resumen', icon: 'grid' },
  { key: 'activities', label: 'Actividades', icon: 'layers' },
  { key: 'submissions', label: 'Entregas', icon: 'clipboard' },
  { key: 'resources', label: 'Recursos', icon: 'book' },
]
const filters = ['Todas', 'Activas', 'Por revisar', 'Próximas', 'Cerradas', 'Borradores']
const submissionFilters = ['Todos', 'Por revisar', 'Entregaron', 'No entregaron', 'Calificados']
const monthIndex: Record<string, number> = { Ene: 0, Feb: 1, Mar: 2, Abr: 3, May: 4, Jun: 5, Jul: 6, Ago: 7, Sep: 8, Oct: 9, Nov: 10, Dic: 11 }
const dateValue = (date: string) => { const [day, month] = date.split(' '); return new Date(2026, monthIndex[month] ?? 0, Number(day)).getTime() }
const fileOptions = ['PDF', 'DOCX', 'PPTX', 'XLSX', 'JPG', 'PNG', 'MP4', 'ZIP']

type Draft = { name: string; description: string; due: string; publish: string; maxFiles: number; maxSize: string; formats: string[]; graded: boolean; gradeCenter: boolean; weight: string; allowReplacement: boolean; allowResubmission: boolean }
type Upload = { name: string; format: string; size: string; progress: number }
type ReviewRecord = { score?: number; scoreMode: 'rubric' | 'manual'; evaluationMode: 'rubric' | 'direct'; criteria: RubricCriterion[]; feedback: string; comments: string[]; status: Student['status'] }
const makeReviewRecord = (student: Student): ReviewRecord => ({
  score: student.status === 'Calificada' ? student.score : undefined,
  scoreMode: 'manual',
  evaluationMode: 'direct',
  criteria: rubric.map((item) => ({ ...item, score: student.status === 'Calificada' ? item.score : 0, expanded: item.id === 'analysis' })),
  feedback: student.id === 'student-3' ? 'Tu análisis conecta con claridad la observación y la evidencia.' : '',
  comments: [],
  status: student.status,
})

function App() {
  const [view, setView] = useState<ViewKey>('home')
  const [collapsed, setCollapsed] = useState(false)
  const [dark, setDark] = useState(false)
  const [activities, setActivities] = useState(seedActivities)
  const [selectedActivity, setSelectedActivity] = useState<Activity>(seedActivities[0] ?? emptyActivity)
  const [activityFilter, setActivityFilter] = useState('Todas')
  const [query, setQuery] = useState('')
  const [sortBy, setSortBy] = useState('fecha')
  const [submissionFilter, setSubmissionFilter] = useState('Todos')
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [resourceOpen, setResourceOpen] = useState<typeof resources[number] | null>(null)
  const [reviewIndex, setReviewIndex] = useState<number | null>(null)
  const [previewOpen, setPreviewOpen] = useState(false)
  const [uploaded, setUploaded] = useState<Upload[]>([])
  const [deliverySent, setDeliverySent] = useState(false)
  const [uploadError, setUploadError] = useState('')
  const [reviewRecords, setReviewRecords] = useState<Record<string, ReviewRecord>>({})
  const [toast, setToast] = useState('')
  const [draft, setDraft] = useState<Draft>({ name: '', description: '', due: '2026-10-28', publish: '2026-10-21', maxFiles: 1, maxSize: '25 MB', formats: ['PDF', 'DOCX', 'PPTX'], graded: true, gradeCenter: true, weight: '20%', allowReplacement: true, allowResubmission: true })

  const courseStats = useMemo(() => ({ active: activities.filter((a) => ['Publicada', 'En curso', 'Por revisar'].includes(a.status)).length, review: activities.reduce((sum, a) => sum + Math.max(0, a.submissions - a.graded), 0), upcoming: activities.filter((a) => a.status === 'Próxima').length, drafts: activities.filter((a) => a.status === 'Borrador').length }), [activities])
  const filteredActivities = useMemo(() => {
    const q = query.trim().toLowerCase()
    const result = activities.filter((a) => {
      const textMatch = !q || `${a.name} ${a.type} ${a.formats.join(' ')}`.toLowerCase().includes(q)
      const statusMatch = activityFilter === 'Todas' || (activityFilter === 'Activas' && ['Publicada', 'En curso', 'Por revisar'].includes(a.status)) || (activityFilter === 'Por revisar' && a.status === 'Por revisar') || (activityFilter === 'Próximas' && a.status === 'Próxima') || (activityFilter === 'Cerradas' && a.status === 'Cerrada') || (activityFilter === 'Borradores' && a.status === 'Borrador')
      return textMatch && statusMatch
    })
    return [...result].sort((a, b) => sortBy === 'nombre' ? a.name.localeCompare(b.name) : sortBy === 'pendientes' ? (b.submissions - b.graded) - (a.submissions - a.graded) : sortBy === 'estado' ? a.status.localeCompare(b.status) : dateValue(a.date) - dateValue(b.date))
  }, [activities, activityFilter, query, sortBy])
  const submissions = useMemo(() => seedStudents.map((student, index) => {
    const base = selectedActivity.id === 'mitosis' ? student : ({ ...student, status: index < selectedActivity.graded ? 'Calificada' : index < selectedActivity.submissions ? 'Por revisar' : 'No entregó', score: index < selectedActivity.graded ? student.score : undefined } as Student)
    const record = reviewRecords[`${selectedActivity.id}:${student.id}`]
    return record ? { ...base, status: record.status, score: record.score } : base
  }), [selectedActivity, reviewRecords])
  const currentStudent = reviewIndex === null ? emptyStudent : submissions[reviewIndex] ?? emptyStudent
  const currentReviewKey = `${selectedActivity.id}:${currentStudent.id}`
  const currentRecord = reviewRecords[currentReviewKey] ?? makeReviewRecord(currentStudent)
  const updateCurrentRecord = (patch: Partial<ReviewRecord>) => setReviewRecords((records) => {
    const base = records[currentReviewKey] ?? currentRecord
    return { ...records, [currentReviewKey]: { ...base, ...patch } }
  })

  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 2400); return () => window.clearTimeout(timer) }, [toast])
  useEffect(() => { const onKey = (event: KeyboardEvent) => { if (event.key === 'Escape') { setDrawerOpen(false); setPreviewOpen(false); setResourceOpen(null); setReviewIndex(null) } }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey) }, [])

  function enterCourse() { setView('overview') }
  function selectActivity(activity: Activity) { setSelectedActivity(activity); setView('submissions'); setReviewIndex(null) }
  function createActivity(publish: boolean) { const id = `local-${Date.now()}`; const date = draft.due ? `${draft.due.slice(8, 10)} Oct` : '28 Oct'; const item: Activity = { ...(seedActivities[0] ?? emptyActivity), id, name: draft.name.trim() || 'Nueva actividad', description: draft.description || 'Actividad con entrega digital creada por el docente.', date, dueDate: `${date} · 23:59`, submissions: 0, graded: 0, status: publish ? 'Publicada' : 'Borrador', affectsGradeCenter: draft.gradeCenter, weight: draft.gradeCenter && draft.graded ? draft.weight : undefined, formats: draft.formats, maxFiles: draft.maxFiles, maxSize: draft.maxSize, allowReplacement: draft.allowReplacement, allowResubmission: draft.allowResubmission, resourceCount: 0 }; setActivities((items) => [item, ...items]); setSelectedActivity(item); setDrawerOpen(false); setDraft((d) => ({ ...d, name: '', description: '' })); setToast(publish ? 'Actividad publicada en ClassCORE' : 'Borrador guardado en Actividades con entrega') }
  function acceptFile(file: File) { const format = file.name.split('.').pop()?.toUpperCase() ?? ''; const size = `${(file.size / 1024 / 1024).toFixed(1)} MB`; if (!selectedActivity.formats.includes(format)) { setUploadError(`Formato .${format.toLowerCase()} no permitido. Usa ${selectedActivity.formats.join(', ')}.`); return } if (file.size > Number.parseInt(selectedActivity.maxSize) * 1024 * 1024) { setUploadError(`El archivo supera el máximo de ${selectedActivity.maxSize}.`); return } setUploadError(''); setUploaded((items) => selectedActivity.maxFiles > items.length ? [...items, { name: file.name, format, size, progress: 0 }] : [{ name: file.name, format, size, progress: 0 }]); window.setTimeout(() => setUploaded((items) => items.map((item) => ({ ...item, progress: 100 }))), 450) }
  function sendDelivery() { if (!uploaded.length) { setUploadError('Selecciona un archivo antes de enviar.'); return } setDeliverySent(true); setToast('Entrega enviada correctamente') }

  return <div className={`app-frame ${dark ? 'dark-mode' : 'light-mode'} ${collapsed ? 'sidebar-collapsed' : ''}`}>
    <Sidebar active={view} collapsed={collapsed} setCollapsed={setCollapsed} onHome={() => setView('home')} onNavigate={(next) => { setView(next); setReviewIndex(null) }} dark={dark} setDark={setDark} />
    <main className="main-panel">
      {view === 'home' && <Topbar view={view} onHome={() => setView('home')} dark={dark} setDark={setDark} />}
      {view === 'home' ? <HomeView stats={courseStats} onEnter={enterCourse} /> : <CourseShell view={view} setView={setView} stats={courseStats} selectedActivity={selectedActivity} onNew={() => setDrawerOpen(true)}>{view === 'overview' ? <OverviewView activities={activities} stats={courseStats} selectActivity={selectActivity} /> : view === 'activities' ? <ActivitiesView activities={filteredActivities} total={activities.length} filter={activityFilter} setFilter={setActivityFilter} query={query} setQuery={setQuery} sortBy={sortBy} setSortBy={setSortBy} selectActivity={selectActivity} /> : view === 'resources' ? <ResourcesView onOpen={setResourceOpen} /> : <SubmissionsView activity={selectedActivity} students={submissions} filter={submissionFilter} setFilter={setSubmissionFilter} reviewIndex={reviewIndex} setReviewIndex={setReviewIndex} record={currentRecord} onRecordChange={updateCurrentRecord} onBack={() => setView('activities')} onPreview={() => { setDeliverySent(false); setUploaded([]); setPreviewOpen(true) }} />}</CourseShell>}
    </main>
    {drawerOpen && <ActivityDrawer draft={draft} setDraft={setDraft} onClose={() => setDrawerOpen(false)} onSave={() => createActivity(false)} onPublish={() => createActivity(true)} />}
    {previewOpen && <StudentPreview activity={selectedActivity} uploaded={uploaded} error={uploadError} sent={deliverySent} onClose={() => setPreviewOpen(false)} onFile={acceptFile} onSend={sendDelivery} onRemove={(index) => setUploaded((items) => items.filter((_, i) => i !== index))} />}
    {resourceOpen && <ResourceDetail resource={resourceOpen} onClose={() => setResourceOpen(null)} />}
    {toast && <div className="toast"><span><Icon name="check" size={13} /></span>{toast}</div>}
  </div>
}

function Sidebar({ active, collapsed, setCollapsed, onHome, onNavigate, dark, setDark }: { active: ViewKey; collapsed: boolean; setCollapsed: (v: boolean) => void; onHome: () => void; onNavigate: (v: Exclude<ViewKey, 'home'>) => void; dark: boolean; setDark: (v: boolean) => void }) { return <aside className="sidebar"><div className="brand"><button className={`classcore-home-button ${active === 'home' ? 'active' : ''}`} onClick={onHome} aria-label="ClassCORE · Mis cursos"><span className="brand-mark"><i /><i /></span><span className="brand-word">class<span>CORE</span></span><span className="brand-context">Mis cursos</span></button><button className="collapse-button" onClick={() => setCollapsed(!collapsed)} aria-label="Colapsar menú"><Icon name="chevron" size={15} /></button></div><div className="sidebar-divider" />{active !== 'home' && <><small className="sidebar-caption">EDUCORE · DOCENTE</small><nav>{navItems.map((item) => <button key={item.key} className={active === item.key ? 'active' : ''} onClick={() => onNavigate(item.key)}><Icon name={item.icon} size={17} /><span>{item.label}</span></button>)}</nav></>}<div className="sidebar-bottom"><button onClick={() => setDark(!dark)}><Icon name={dark ? 'spark' : 'lightning'} size={16} /><span>{dark ? 'Light Glass' : 'Dark Glass'}</span></button><button onClick={() => {}}><Icon name="undo" size={16} /><span>Ayuda y atajos</span></button></div><div className="profile"><span>JD</span><div><strong>Docente</strong><small>EduCore Main</small></div></div></aside> }
function Topbar({ view, onHome, dark, setDark }: { view: ViewKey; onHome: () => void; dark: boolean; setDark: (v: boolean) => void }) { return <header className={`topbar ${view === 'overview' ? 'overview-topbar' : ''}`}><div className="breadcrumbs">{view === 'overview' ? <span className="topbar-spacer" /> : <><button onClick={onHome}>EduCore</button><Icon name="chevron" size={13} /><strong>{view === 'home' ? 'ClassCORE' : 'ClassCORE'}</strong>{view !== 'home' && <><Icon name="chevron" size={13} /><span>Curso · Asignatura</span></>}</>}</div><div className="top-actions"><button className="search-trigger" onClick={onHome}><Icon name="search" size={15} /><span>Buscar</span><kbd>⌘ K</kbd></button><button className="icon-button notification-button" aria-label="Notificaciones" title="Notificaciones"><Icon name="bell" size={17} /><i aria-hidden="true" /></button><button className="top-avatar">JD</button><button className="theme-mini" onClick={() => setDark(!dark)}>{dark ? 'Dark' : 'Light'}</button></div></header> }
function CourseShell({ children, view, setView, stats, selectedActivity, onNew }: { children: React.ReactNode; view: ViewKey; setView: (v: ViewKey) => void; stats: { active: number; review: number; upcoming: number; drafts: number }; selectedActivity: Activity; onNew: () => void }) { return <><section className="course-header compact-course-header"><div className="course-identity"><span className="course-identity-mark"><Icon name="book" size={18} /></span><div className="course-identity-copy"><h1><span className="course-code">Curso</span><span className="course-name">Asignatura</span></h1><p>{stats.active} actividades activas · {stats.review} por revisar</p></div></div><div className="course-header-actions"><button className="primary-button" onClick={onNew}><Icon name="plus" size={15} /> Nueva actividad</button></div></section><nav className="course-tabs course-tabs-v3 module-navigation compact-module-navigation" aria-label="Navegación del curso"><div className="course-nav-bubbles"><button title="Resumen del curso" className={`nav-bubble ${view === 'overview' ? 'active' : ''}`} onClick={() => setView('overview')}><Icon name="chart" size={16} /><span>Resumen</span></button><button title="Actividades con entrega" className={`nav-bubble ${view === 'activities' ? 'active' : ''}`} onClick={() => setView('activities')}><Icon name="layers" size={16} /><span>Actividades</span></button><button title={`${stats.review} entregas por revisar`} className={`nav-bubble ${view === 'submissions' ? 'active' : ''}`} onClick={() => setView('submissions')}><Icon name="clipboard" size={16} /><span>Entregas</span><em>{stats.review}</em></button><button title="Recursos del curso" className={`nav-bubble ${view === 'resources' ? 'active' : ''}`} onClick={() => setView('resources')}><Icon name="book" size={16} /><span>Recursos</span></button></div></nav><div className="content-area">{children}</div></> }
function HomeView({ stats, onEnter }: { stats: { active: number; review: number; upcoming: number; drafts: number }; onEnter: () => void }) { return <div className="home-content"><div className="page-intro classcore-hero"><div><span className="eyebrow classroom-eyebrow"><i /> EDUCORE / AULA VIRTUAL</span><div className="identity-lockup"><span className="identity-orbit"><i /><i /><b /></span><h1>Classroom</h1></div><p className="hero-subtitle"><Icon name="spark" size={14} /> Conecta tus asignaturas · Periodo académico</p></div><div className="hero-context"><div className="context-card"><span className="context-card-icon"><Icon name="book" size={17} /></span><span><small>CICLO LECTIVO</small><strong>Periodo académico</strong><em><Icon name="clock" size={11} /> Actualizado hoy</em></span></div></div></div><div className="global-summary classcore-kpis"><Summary value={String(courses.length)} label="Cursos activos" detail="Espacios docentes" icon="book" tone="cyan" /><Summary value={String(stats.review)} label="Entregas" detail="Por revisar" icon="clipboard" tone="mint" /><Summary value={String(stats.upcoming)} label="Pendientes" detail="Próximas actividades" icon="chart" tone="amber" /><Summary value={String(stats.drafts)} label="Evaluaciones" detail="En seguimiento" icon="layers" tone="violet" /></div><div className="section-heading"><div><h2>Mis cursos</h2><p>Los espacios donde gestionas tus actividades y entregas.</p></div></div><div className="course-grid">{courses.map((course, index) => <article className={`course-card glass-card course-${course.tone} ${index === 0 ? 'featured' : ''}`} key={course.name}><div className="course-card-top"><span className={`course-symbol ${course.tone}`}><Icon name={course.icon} size={22} /></span><div className="course-card-top-meta"><span className="course-badge">{course.code}</span>{index === 0 && <span className="current-tag">ACTIVO</span>}</div></div><h3>{course.name}</h3><p className="course-meta">{course.students} estudiantes</p><div className="course-facts"><span><b>{course.active}</b><small>actividades activas</small></span><span><b>{course.review}</b><small>por revisar</small></span><span><small>Próxima entrega</small><b>{course.next}</b></span></div><button className={`course-cta ${index === 0 ? 'primary-button' : 'outline-button'}`} onClick={onEnter}>{index === 0 ? 'Entrar al curso' : 'Ver curso'} <Icon name="arrow" size={15} /></button></article>)}</div>{!courses.length && <div className="empty-state home-empty-state"><Icon name="book" size={20} /><strong>Conecta tus asignaturas desde EduCore</strong><p>La interfaz está lista para recibir los cursos del sistema principal.</p></div>}<div className="home-note glass-card"><Icon name="lightning" size={18} /><div><strong>Módulo EduCore · entregas digitales</strong><p>ClassCORE concentra las actividades que necesitan archivo, evidencia y revisión docente.</p></div></div></div> }
function Summary({ value, label, detail, icon, tone }: { value: string; label: string; detail?: string; icon: string; tone: string }) { return <div className="summary-card glass-card"><span className={`summary-icon ${tone}`}><Icon name={icon} size={17} /></span><div><span className="summary-label">{label}</span><strong>{value}</strong>{detail && <small>{detail}</small>}</div></div> }
function OverviewView({ activities, stats, selectActivity }: { activities: Activity[]; stats: { active: number; review: number; upcoming: number }; selectActivity: (a: Activity) => void }) { const recent = activities.slice(0, 4); return <section className="view-section overview-view"><div className="overview-title"><div><span className="eyebrow">PANORAMA DEL CURSO</span><h2>Panorama del curso</h2><p>Lo que requiere atención y lo que viene después.</p></div><span className="date-chip">08 — 14 OCT</span></div><div className="operational-metrics overview-kpis"><Summary value={String(stats.review)} label="Por revisar" icon="clipboard" tone="amber" /><Summary value={String(stats.active)} label="Actividades activas" icon="layers" tone="cyan" /><Summary value={String(stats.upcoming)} label="Próximas" icon="chart" tone="violet" /><Summary value="42" label="Entregas esta semana" icon="download" tone="mint" /></div><div className="overview-columns"><section className="glass-card compact-section"><SectionLabel>Actividades recientes</SectionLabel><div className="recent-list">{recent.map((activity) => { const progress = Math.round((activity.submissions / 38) * 100); const pending = Math.max(0, activity.submissions - activity.graded); return <button className="recent-row" key={activity.id} onClick={() => selectActivity(activity)}><span className={`activity-icon ${activity.accent}`}>{activity.icon}</span><span className="recent-main"><strong>{activity.name}</strong><small>{activity.type} · {activity.submissions}/38 entregaron</small><span className="recent-progress"><i style={{ width: `${progress}%` }} /></span></span><span className={pending ? "recent-review" : activity.submissions === 38 ? "recent-complete" : "recent-empty"}>{pending ? <><b>{pending}</b><small>pendientes</small></> : activity.submissions === 38 ? <><Icon name="check" size={13} /> Completada</> : <><b>{activity.submissions}</b><small>entregas</small></>}</span><span className="recent-date">{activity.date}</span><Icon name="chevron" size={15} /></button> })}</div></section><section className="glass-card compact-section upcoming-section"><SectionLabel>Próximas entregas</SectionLabel>{activities.filter((a) => ['Próxima', 'En curso'].includes(a.status)).slice(0, 4).map((activity) => <button className="upcoming-row" key={activity.id} onClick={() => selectActivity(activity)}><span className="upcoming-date"><b>{activity.date.split(' ')[0]}</b><small>{activity.date.split(' ')[1]}</small></span><span className="upcoming-main"><strong>{activity.name}</strong><small><b>{activity.dueDate.split(' · ')[1]}</b> · {activity.type}</small></span><Icon name="chevron" size={14} /></button>)}</section></div></section> }
function ActivitiesView({ activities, total, filter, setFilter, query, setQuery, sortBy, setSortBy, selectActivity }: { activities: Activity[]; total: number; filter: string; setFilter: (v: string) => void; query: string; setQuery: (v: string) => void; sortBy: string; setSortBy: (v: string) => void; selectActivity: (a: Activity) => void }) { const [density, setDensity] = useState<'comfortable' | 'compact'>('comfortable'); return <section className="view-section activities-view activity-workspace"><div className="activity-workspace-heading"><div><span className="eyebrow">WORKSPACE DE ENTREGAS · {total}</span><h2>Actividades con entrega</h2><p>Un espacio para crear, publicar, recibir y revisar trabajos digitales.</p></div><div className="activity-flow"><span className="flow-step done"><i>1</i>Crear</span><b>→</b><span className="flow-step done"><i>2</i>Publicar</span><b>→</b><span className="flow-step"><i>3</i>Recibir</span><b>→</b><span className="flow-step"><i>4</i>Revisar</span></div></div><div className="activity-controls"><div className="activity-search search-box"><Icon name="search" size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar actividad…" /><kbd>⌘ K</kbd></div><div className="activity-filter-pills">{filters.map((item) => <button key={item} className={filter === item ? 'selected' : ''} onClick={() => setFilter(item)}>{item}</button>)}</div><div className="activity-density" aria-label="Densidad de vista"><button className={density === 'comfortable' ? 'selected' : ''} onClick={() => setDensity('comfortable')}><Icon name="layers" size={13} /> Cómoda</button><button className={density === 'compact' ? 'selected' : ''} onClick={() => setDensity('compact')}><Icon name="grid" size={13} /> Compacta</button></div><label className="activity-sort"><span>Ordenar</span><select value={sortBy} onChange={(e) => setSortBy(e.target.value)}><option value="fecha">Fecha límite</option><option value="pendientes">Pendientes</option><option value="estado">Estado</option><option value="nombre">Nombre</option></select></label></div><div className={`activity-object-grid ${density === 'compact' ? 'compact-density' : 'comfortable-density'}`}>{activities.map((activity) => { const pending = Math.max(0, activity.submissions - activity.graded); const progress = Math.round((activity.submissions / 38) * 100); return <button className={`activity-object glass-card ${activity.accent}`} key={activity.id} onClick={() => selectActivity(activity)}><div className="activity-object-accent" /><div className="activity-object-top"><span className={`activity-object-icon ${activity.accent}`}><Icon name={activity.icon === '↗' ? 'arrow' : activity.icon === '▤' ? 'book' : activity.icon === '◇' ? 'spark' : activity.icon === '✦' ? 'layers' : 'clipboard'} size={21} /></span><StatusPill status={activity.status} /><span className="object-open"><Icon name="arrow" size={15} /></span></div><div className="activity-object-title"><span className="activity-object-type">{activity.type} · Entrega digital</span><h3>{activity.name}</h3><p>{activity.description}</p></div><div className="activity-object-meta"><span><small>Fecha límite</small><strong>{activity.date}</strong><em>{activity.dueDate.split(' · ')[1]}</em></span><span><small>Entregas</small><strong>{activity.submissions}<em> / 38</em></strong><div className="object-progress"><i style={{ width: `${progress}%` }} /></div></span><span className={pending ? 'needs-review' : ''}><small>Por revisar</small><strong>{pending}</strong><em>{pending ? 'requieren atención' : 'al día'}</em></span></div><div className="activity-object-footer"><span className={activity.affectsGradeCenter ? 'grade-link' : 'no-grade'}><Icon name="chart" size={13} /> {activity.affectsGradeCenter ? `Grade Center · ${activity.weight ?? 'sin peso'}` : 'Solo ClassCORE'}</span><span className="object-formats">{activity.formats.slice(0, 3).join(' · ')}</span></div></button> })}{!activities.length && <div className="empty-state"><Icon name="search" size={20} /><strong>No encontramos actividades</strong><p>Prueba otro filtro o término.</p></div>}</div><div className="activity-workspace-footer">Mostrando <b>{activities.length}</b> de {total} actividades con entrega <span>Selecciona una actividad para abrir sus entregas y revisión</span></div></section> }
function SubmissionsView({ activity, students, filter, setFilter, reviewIndex, setReviewIndex, record, onRecordChange, onBack, onPreview }: { activity: Activity; students: Student[]; filter: string; setFilter: (v: string) => void; reviewIndex: number | null; setReviewIndex: (v: number | null) => void; record: ReviewRecord; onRecordChange: (patch: Partial<ReviewRecord>) => void; onBack: () => void; onPreview: () => void }) {
  const [search, setSearch] = useState('')
  const [exported, setExported] = useState(false)
  if (reviewIndex !== null) return <ReviewView activity={activity} students={students} index={reviewIndex} setIndex={setReviewIndex} record={record} onRecordChange={onRecordChange} onBack={() => setReviewIndex(null)} />
  const delivered = students.filter((student) => student.status !== 'No entregó').length
  const pending = students.filter((student) => student.status === 'Por revisar').length
  const missing = students.filter((student) => student.status === 'No entregó').length
  const graded = students.filter((student) => student.status === 'Calificada').length
  const counts: Record<string, number> = { Todos: students.length, 'Por revisar': pending, Entregaron: delivered, 'No entregaron': missing, Calificados: graded }
  const normalizedSearch = search.trim().toLowerCase()
  const visibleStudents = students.filter((student) => {
    const filterMatch = filter === 'Todos' || (filter === 'Por revisar' && student.status === 'Por revisar') || (filter === 'Entregaron' && student.status !== 'No entregó') || (filter === 'No entregaron' && student.status === 'No entregó') || (filter === 'Calificados' && student.status === 'Calificada')
    const searchMatch = !normalizedSearch || `${student.name} ${student.group} ${student.file ?? ''}`.toLowerCase().includes(normalizedSearch)
    return filterMatch && searchMatch
  })
  const progress = students.length ? Math.round((delivered / students.length) * 100) : 0
  const exportList = () => { setExported(true); window.setTimeout(() => setExported(false), 2200) }
  return <section className="view-section submissions-view"><button className="backline" onClick={onBack}><Icon name="chevron" size={14} /> Actividades con entrega</button><div className="detail-heading submission-heading"><div className="submission-header-copy"><span className="eyebrow">ACTIVIDAD · {activity.status.toUpperCase()}</span><h2>{activity.name}</h2><p>{activity.description}</p><div className="submission-summary"><strong>{delivered}<small>/ {students.length}</small><span>entregaron</span></strong><strong className="review-priority">{pending}<span>por revisar</span></strong><strong className="missing-count">{missing}<span>no entregaron</span></strong></div><div className="submission-progress" aria-label={`${progress}% de entregas recibidas`}><span style={{ width: `${progress}%` }} /></div><div className="submission-progress-meta"><span>{progress}% recibido</span><span>{graded} calificadas</span></div></div><div className="submission-header-side"><div><small>Fecha límite</small><strong>{activity.dueDate}</strong></div><div><small>Tipo de entrega</small><strong>{activity.type}</strong></div><div><small>Formatos</small><strong>{activity.formats.join(' · ')}</strong></div><div><small>Grade Center</small><strong className={activity.affectsGradeCenter ? 'violet' : 'muted'}>{activity.affectsGradeCenter ? `Sí · ${activity.weight ?? 'sin peso'}` : 'No impacta'}</strong></div></div></div><div className="submission-tools submission-workspace-tools"><div className="submission-search"><Icon name="search" size={15} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar estudiante, grupo o archivo…" /></div><div className="submission-filter-pills">{submissionFilters.map((item) => <button key={item} className={filter === item ? 'selected' : ''} onClick={() => setFilter(item)}>{item}<b>{counts[item]}</b></button>)}</div><button className="primary-button open-grader-action" onClick={() => { const firstPending = students.findIndex((student) => student.status === 'Por revisar'); setReviewIndex(firstPending >= 0 ? firstPending : 0) }} disabled={!pending}><Icon name="check" size={14} /> Abrir calificador</button><button className="ghost-button export-action" onClick={exportList}><Icon name="download" size={14} /> Exportar</button>{exported && <span className="export-feedback"><Icon name="check" size={12} /> CSV preparado</span>}</div><div className="submission-list workspace-submission-list"><div className="submission-list-head"><span>Entrega digital</span><span>{visibleStudents.length} de {students.length} visibles</span></div><div className="submission-cards">{visibleStudents.map((student) => { const originalIndex = students.findIndex((item) => item.id === student.id); return <button className={`submission-row-card ${student.status === 'Por revisar' ? 'needs-review' : student.status === 'No entregó' ? 'not-submitted' : 'graded'}`} key={student.id} onClick={() => setReviewIndex(originalIndex)}><span className="submission-student"><i style={{ background: student.color }}>{student.initials}</i><span><strong>{student.name}</strong><small>{student.group} · {student.status === 'No entregó' ? 'Pendiente de entrega' : `entregó ${student.time ?? 'recientemente'}`}</small></span></span><span className="submission-file"><Icon name={student.file ? 'file' : 'clock'} size={17} /><span>{student.file ? <><strong>{student.file}</strong><small>{student.fileSize} · {student.fileType ?? activity.formats[0]}</small></> : <><strong>Sin entrega</strong><small>La fecha límite sigue pendiente</small></>}</span></span><Status status={student.status} /><span className="submission-grade">{student.score ? <><b>{student.score.toFixed(1)}</b><small>/ 5.0</small></> : <span>—</span>}</span><span className="submission-review-action">Revisar <Icon name="arrow" size={14} /></span></button> })}</div>{!visibleStudents.length && <div className="submission-empty"><Icon name="search" size={22} /><strong>No encontramos entregas</strong><span>Prueba con otro estudiante, grupo o archivo.</span></div>}</div></section>
}
function Fact({ label, value, tone = '' }: { label: string; value: string; tone?: string }) { return <div><small>{label}</small><strong className={tone}>{value}</strong></div> }
function Status({ status }: { status: Student['status'] }) { const tone = status === 'Por revisar' ? 'review' : status === 'Calificada' ? 'done' : status === 'No entregó' ? 'absent' : 'delivered'; return <span className={`status-text ${tone}`}><i />{status}</span> }
function ReviewView({ activity, students, index, setIndex, record, onRecordChange, onBack }: { activity: Activity; students: Student[]; index: number; setIndex: (v: number | null) => void; record: ReviewRecord; onRecordChange: (patch: Partial<ReviewRecord>) => void; onBack: () => void }) {
  const student = students[index] ?? emptyStudent
  const [studentQuery, setStudentQuery] = useState('')
  const [studentFilter, setStudentFilter] = useState('Todos')
  const [zoom, setZoom] = useState(87)
  const [page, setPage] = useState(1)
  const [focusMode, setFocusMode] = useState(false)
  const [mobilePanel, setMobilePanel] = useState<'students' | 'evidence' | 'review'>('evidence')
  const [gradeText, setGradeText] = useState(record.score === undefined ? '' : String(record.score))
  const [gradeError, setGradeError] = useState('')
  const [comment, setComment] = useState('')
  const [showCommentComposer, setShowCommentComposer] = useState(false)
  const [showQuickComments, setShowQuickComments] = useState(false)
  const quickComments = ['Conecta la evidencia con la conclusión.', 'Justifica mejor tu conclusión.', 'Incluye datos concretos del experimento.', 'Revisa la presentación y el orden de la evidencia.']
  const [syncState, setSyncState] = useState(record.status === 'Calificada' ? 'Sincronizado' : 'Sin cambios')
  const total = record.criteria.reduce((sum, item) => sum + item.score, 0)
  const max = record.criteria.reduce((sum, item) => sum + item.max, 0)
  const rubricScore = Number(((total / max) * 5).toFixed(1))
  const pendingIndexes = students.map((item, itemIndex) => item.status === 'Por revisar' ? itemIndex : -1).filter((itemIndex) => itemIndex >= 0)
  const pendingPosition = pendingIndexes.indexOf(index)
  const filteredStudents = students.filter((item) => {
    const filterMatch = studentFilter === 'Todos' || (studentFilter === 'Pendientes' && item.status === 'Por revisar') || (studentFilter === 'Calificados' && item.status === 'Calificada') || (studentFilter === 'No entregaron' && item.status === 'No entregó')
    const queryMatch = !studentQuery.trim() || `${item.name} ${item.group} ${item.file ?? ''}`.toLowerCase().includes(studentQuery.trim().toLowerCase())
    return filterMatch && queryMatch
  })
  const nextPending = (direction: 1 | -1 = 1) => {
    if (!pendingIndexes.length) return index
    const current = pendingIndexes.indexOf(index)
    return current < 0 ? (direction === 1 ? pendingIndexes[0] : pendingIndexes[pendingIndexes.length - 1]) : pendingIndexes[current + direction] ?? index
  }
  const markChanged = (patch: Partial<ReviewRecord>) => { onRecordChange({ ...patch, status: 'Por revisar' }); setSyncState('Cambios sin guardar') }
  const updateCriterionScore = (criterionIndex: number, value: string) => {
    const parsed = Number(value)
    if (Number.isNaN(parsed)) return
    const nextCriteria = record.criteria.map((item, idx) => idx === criterionIndex ? { ...item, score: Math.max(0, Math.min(item.max, parsed)), expanded: true } : item)
    const nextTotal = nextCriteria.reduce((sum, item) => sum + item.score, 0)
    const nextCalculatedScore = Number(((nextTotal / max) * 5).toFixed(1))
    onRecordChange({ criteria: nextCriteria, score: nextCalculatedScore, scoreMode: 'rubric', evaluationMode: 'rubric', status: 'Por revisar' })
    setGradeText(String(nextCalculatedScore))
    setGradeError('')
    setSyncState('Cambios sin guardar')
  }
  const changeGrade = (value: string) => {
    setGradeText(value)
    const parsed = Number(value)
    if (!value || Number.isNaN(parsed) || parsed < 0 || parsed > 5) { setGradeError('Usa un valor entre 0.0 y 5.0'); setSyncState('Cambios sin guardar'); return }
    setGradeError('')
    markChanged({ score: parsed, scoreMode: 'manual' })
  }
  const setEvaluationMode = (mode: 'rubric' | 'direct') => {
    if (mode === 'rubric') {
      const nextScore = total > 0 ? rubricScore : undefined
      onRecordChange({ evaluationMode: 'rubric', scoreMode: 'rubric', score: nextScore, status: 'Por revisar' })
      setGradeText(nextScore === undefined ? '' : String(nextScore))
    } else {
      onRecordChange({ evaluationMode: 'direct', scoreMode: 'manual', status: 'Por revisar' })
    }
    setGradeError('')
    setSyncState('Cambios sin guardar')
  }
  const saveReview = () => {
    if (!student.file) { setGradeError('No hay evidencia digital para calificar.'); return false }
    const parsed = Number(gradeText)
    if (record.evaluationMode === 'rubric' && total === 0) { setGradeError('Evalúa al menos un criterio de la rúbrica antes de continuar.'); return false }
    if (record.evaluationMode === 'direct' && (!gradeText || Number.isNaN(parsed) || parsed < 0 || parsed > 5)) { setGradeError('Asigna una calificación entre 0.0 y 5.0 antes de continuar.'); return false }
    const finalScore = record.evaluationMode === 'rubric' ? rubricScore : parsed
    onRecordChange({ score: finalScore, scoreMode: record.evaluationMode === 'rubric' ? 'rubric' : 'manual', status: 'Calificada' })
    setGradeText(String(finalScore))
    setGradeError('')
    setSyncState('Guardado · Sincronizado')
    return true
  }
  const saveAndNext = () => { if (!saveReview()) return; const next = nextPending(1); if (next === index) { setSyncState('Guardado · todo revisado'); return } setIndex(next) }
  const publishComment = () => { const text = comment.trim(); if (!text) return; onRecordChange({ comments: [...record.comments, text], status: record.status }); setComment(''); setShowCommentComposer(false); setShowQuickComments(false); setSyncState('Cambios sin guardar') }
  const chooseQuickComment = (text: string) => { setComment((current) => current ? `${current} ${text}` : text); setShowCommentComposer(true); setShowQuickComments(false) }
  useEffect(() => { setGradeText(record.score === undefined ? '' : String(record.score)); setGradeError(''); setSyncState(record.status === 'Calificada' ? 'Sincronizado' : 'Sin cambios'); setZoom(87); setPage(1); setComment(''); setShowCommentComposer(false); setShowQuickComments(false) }, [student.id])
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 's') { event.preventDefault(); saveReview(); return }
      if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return
      if (event.key.toLowerCase() === 'j' || event.key === 'ArrowDown') { event.preventDefault(); setIndex(nextPending(1)) }
      if (event.key.toLowerCase() === 'k' || event.key === 'ArrowUp') { event.preventDefault(); setIndex(nextPending(-1)) }
      if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); saveAndNext() }
      if (event.key === 'Enter' && event.shiftKey) { event.preventDefault(); setIndex(nextPending(-1)) }
      if (event.key === 'Escape') onBack()
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [index, gradeText, record, gradeError, students, pendingIndexes])
  return <section className={`review-view ${focusMode ? 'review-classroom-focus' : ''}`} data-panel={mobilePanel}>
    <div className="review-toolbar"><button className="backline" onClick={onBack}><Icon name="chevron" size={14} /> Entregas</button><button className={`focus-toggle classroom-focus-button ${focusMode ? 'active' : ''}`} onClick={() => setFocusMode(!focusMode)} aria-label={focusMode ? 'Cerrar enfoque del classroom' : 'Expandir classroom'}><Icon name="expand" size={14} /> {focusMode ? 'Cerrar enfoque' : 'Expandir classroom'}</button><span className="key-hint"><kbd>J</kbd>/<kbd>K</kbd> navegar · <kbd>Ctrl/Cmd S</kbd> guardar · <kbd>Enter</kbd> siguiente</span></div>
    <div className="review-context-bar"><div className="context-identity"><i className="context-avatar" style={{ background: student.color }}>{student.initials}</i><div><strong>{student.name} · {student.group}</strong><span>{activity.name}</span><small className={`context-status ${student.status === 'Por revisar' ? 'needs' : student.status === 'Calificada' ? 'done' : 'missing'}`}><i />{student.status === 'No entregó' ? 'No entregó' : `${student.status} · ${student.time ?? 'entrega registrada'}`}</small></div></div><div className="review-context-progress"><b>{pendingPosition >= 0 ? pendingPosition + 1 : '—'} <small>de {pendingIndexes.length} pendientes</small></b><button onClick={() => setIndex(nextPending(-1))} disabled={!pendingIndexes.length}><Icon name="chevron" size={14} /> Anterior</button><button onClick={() => setIndex(nextPending(1))} disabled={!pendingIndexes.length}>Siguiente <Icon name="arrow" size={14} /></button></div></div>
    <nav className="review-mobile-tabs" aria-label="Panel del calificador"><button className={mobilePanel === 'students' ? 'active' : ''} onClick={() => setMobilePanel('students')}><Icon name="users" size={15} /> Estudiantes · {students.length}</button><button className={mobilePanel === 'evidence' ? 'active' : ''} onClick={() => setMobilePanel('evidence')}><Icon name="file" size={15} /> Evidencia</button><button className={mobilePanel === 'review' ? 'active' : ''} onClick={() => setMobilePanel('review')}><Icon name="check" size={15} /> Revisión · {record.score === undefined ? '—' : record.score.toFixed(1)}</button></nav>
    <div className="review-grid">
      <aside className="review-students glass-card"><div className="panel-heading"><div><strong>Estudiantes</strong><span>{students.filter((s) => s.status !== 'No entregó').length} con entrega · {pendingIndexes.length} pendientes</span></div></div><div className="grader-search"><Icon name="search" size={14} /><input value={studentQuery} onChange={(event) => setStudentQuery(event.target.value)} placeholder="Buscar estudiante, grupo…" /></div><div className="grader-filters">{['Todos', 'Pendientes', 'Calificados', 'No entregaron'].map((item) => <button key={item} className={studentFilter === item ? 'active' : ''} onClick={() => setStudentFilter(item)}>{item}</button>)}</div><div className="student-scroll">{filteredStudents.map((item) => { const itemIndex = students.findIndex((entry) => entry.id === item.id); return <button key={item.id} className={`grader-student ${itemIndex === index ? 'active' : ''} ${item.status === 'Por revisar' ? 'student-needs-review' : item.status === 'No entregó' ? 'student-missing' : 'student-graded'}`} onClick={() => { setIndex(itemIndex); setMobilePanel('evidence') }}><i style={{ background: item.color }}>{item.initials}</i><span><strong>{item.name}</strong><small>{item.group} · {item.status === 'No entregó' ? 'Sin entrega' : item.file ?? 'Entrega recibida'}</small></span><em>{item.status === 'Por revisar' ? 'Pendiente' : item.status === 'No entregó' ? 'No entregó' : item.score ? item.score.toFixed(1) : 'Lista'}</em></button> })}</div></aside>
      <main className="file-viewer glass-card"><div className="viewer-top"><div><span className="file-icon"><Icon name={student.file ? 'file' : 'clock'} size={17} /></span><span><strong>{student.file ?? 'Sin entrega recibida'}</strong><small>{student.file ? `${student.fileType ?? activity.formats[0]} · ${student.fileSize ?? 'Tamaño no disponible'} · ${student.time ?? 'Entrega registrada'}` : 'Este estudiante no registra un archivo'}</small></span></div><div className="viewer-actions" aria-label="Herramientas de evidencia"><span className="viewer-mode-label">Evidencia vinculada</span></div></div><div className={`document-canvas ${student.file ? '' : 'empty-evidence'}`}><div className="document-sheet" style={{ transform: `rotate(-.8deg) scale(${zoom / 87})` }}>{student.file ? <><div className="doc-brand"><span>CURSO</span><span>ASIGNATURA</span></div><div className="doc-line short" /><h2>{activity.name}</h2><p className="doc-lead">Vista previa del archivo enviado por {student.name}. El contenido se mostrará aquí según el formato recibido.</p><div className="doc-placeholder"><Icon name="file" size={28} /><strong>Archivo listo para revisar</strong><small>Visor conceptual · página {page} de 3</small></div><div className="doc-highlight">La evidencia digital queda vinculada a las instrucciones y a la revisión docente.</div></> : <div className="evidence-empty-content"><Icon name="clock" size={34} /><strong>No entregó esta actividad</strong><span>No hay evidencia digital para revisar.</span><small>La fecha límite es {activity.dueDate}.</small></div>}</div><div className="viewer-zoom"><button onClick={() => setZoom(Math.max(60, zoom - 10))} aria-label="Reducir zoom">−</button><span>{zoom}%</span><button onClick={() => setZoom(Math.min(130, zoom + 10))} aria-label="Aumentar zoom">+</button></div></div><div className="viewer-footer"><span><i className="online-dot" /> Visor de evidencia</span><span>{student.file ? <><button onClick={() => setPage(Math.max(1, page - 1))} disabled={page === 1} aria-label="Página anterior">‹</button> Página {page} de 3 <button onClick={() => setPage(Math.min(3, page + 1))} disabled={page === 3} aria-label="Página siguiente">›</button></> : 'Sin páginas disponibles'}</span></div></main>
      <aside className="review-panel glass-card"><div className="score-header"><div><strong>Revisión</strong><span>{activity.name}</span></div><span className={`score-state ${activity.affectsGradeCenter ? 'grade-linked' : ''}`}>{activity.affectsGradeCenter ? `Grade Center · ${activity.weight ?? 'sin peso'}` : 'Solo ClassCORE'}</span></div><div className="evaluation-mode"><span>Método de evaluación</span><div><button className={record.evaluationMode === 'rubric' ? 'active' : ''} onClick={() => setEvaluationMode('rubric')} disabled={!student.file}>Rúbrica</button><button className={record.evaluationMode === 'direct' ? 'active' : ''} onClick={() => setEvaluationMode('direct')} disabled={!student.file}>Nota directa</button></div></div><div className="score-input-wrap"><input aria-label="Calificación de 0.0 a 5.0" value={gradeText} disabled={!student.file || record.evaluationMode === 'rubric'} onChange={(event) => changeGrade(event.target.value)} placeholder="—" /><span>/ 5.0</span></div>{gradeError && <div className="grade-error"><Icon name="alert" size={13} /> {gradeError}</div>}<div className="score-bar"><span style={{ width: `${Math.max(0, Math.min(100, (record.score ?? 0) / 5 * 100))}%` }} /></div><div className="score-meta"><span>{record.evaluationMode === 'rubric' ? 'Nota calculada por criterios' : 'Nota directa · rúbrica no aplicada'}</span><small>{record.evaluationMode === 'rubric' ? 'Edita los puntos de cada criterio para actualizar la nota.' : 'La nota se registra sin utilizar la rúbrica.'}</small></div>{record.evaluationMode === 'rubric' ? <><div className="rubric-heading"><SectionLabel action={<span className="tiny-label">{total}/{max}</span>}>Rúbrica</SectionLabel></div><div className="rubric-list">{record.criteria.map((criterion, i) => <div className={`rubric-item ${criterion.expanded ? 'expanded' : ''}`} key={criterion.id}><button className="rubric-trigger" disabled={!student.file} onClick={() => onRecordChange({ criteria: record.criteria.map((item, idx) => idx === i ? { ...item, expanded: !item.expanded } : item) })}><span><i className="rubric-dot" />{criterion.title}</span><b>{criterion.score}/{criterion.max}<Icon name={criterion.expanded ? 'down' : 'chevron'} size={12} /></b></button>{criterion.expanded && <div className="rubric-detail"><p>{criterion.description}</p><label><span>Puntos obtenidos</span><input type="number" min={0} max={criterion.max} step={1} value={criterion.score} disabled={!student.file} aria-label={`Puntos de ${criterion.title}`} onChange={(event) => updateCriterionScore(i, event.target.value)} /></label></div>}<div className="rubric-progress"><span style={{ width: `${Math.max(0, Math.min(100, (criterion.score / criterion.max) * 100))}%` }} /></div></div>)}</div></> : <div className="rubric-disabled-note"><span><Icon name="layers" size={15} /><strong>Rúbrica no aplicada</strong><small>La evaluación se realizará con una nota directa.</small></span><button onClick={() => setEvaluationMode('rubric')} disabled={!student.file}>Integrar rúbrica</button></div>}<div className="comment-section comment-only"><div className="comment-section-head"><strong><Icon name="message" size={15} /> Comentarios</strong><span>{record.comments.length}</span><button type="button" className="comment-add-toggle" disabled={!student.file} onClick={() => setShowCommentComposer((open) => !open)}>{showCommentComposer ? 'Cerrar editor' : 'Agregar comentario'} <Icon name={showCommentComposer ? 'close' : 'plus'} size={13} /></button></div>{showCommentComposer && <div className="comment-composer-shell"><p className="comment-helper">Agrega una observación breve para dejar contexto de la revisión.</p><div className="quick-comments-toggle-row"><span>¿Necesitas una frase?</span><button type="button" onClick={() => setShowQuickComments((open) => !open)}><Icon name="layers" size={13} /> {showQuickComments ? 'Ocultar comentarios rápidos' : 'Ver comentarios rápidos'} <Icon name={showQuickComments ? 'down' : 'chevron'} size={11} /></button></div>{showQuickComments && <div className="quick-comments"><span>Selecciona una opción para editarla</span><div>{quickComments.map((item) => <button type="button" key={item} onClick={() => chooseQuickComment(item)}>{item}</button>)}</div></div>}<div className="comment-compose"><textarea value={comment} disabled={!student.file} onChange={(e) => setComment(e.target.value)} placeholder="Escribe un comentario…" /><button aria-label="Agregar comentario" disabled={!comment.trim() || !student.file} onClick={publishComment}><Icon name="arrow" size={14} /></button></div></div>}<div className="comment-list">{record.comments.length ? record.comments.map((item, commentIndex) => <div className="comment-item new-comment" key={`${item}-${commentIndex}`}><i>JD</i><div><strong>Docente <small>Ahora</small></strong><p>{item}</p></div></div>) : <div className="comment-empty"><Icon name="message" size={16} /><span>Aún no hay comentarios. Agrega una observación para dejar contexto.</span></div>}</div></div><div className="panel-footer"><span className={`saved ${syncState.includes('Sincronizado') ? 'is-synced' : syncState.includes('Cambios') ? 'is-dirty' : ''}`}><Icon name={syncState.includes('Sincronizado') ? 'check' : syncState.includes('Cambios') ? 'alert' : 'clock'} size={13} /> {syncState}</span><button className="primary-button" onClick={saveAndNext} disabled={!student.file || !!gradeError}>Guardar y siguiente pendiente <Icon name="arrow" size={14} /></button></div></aside>
    </div>
  </section>
}
function ResourcesView({ onOpen }: { onOpen: (resource: typeof resources[number]) => void }) { return <section className="view-section resources-view"><div className="section-heading"><div><span className="eyebrow">BIBLIOTECA DEL CURSO</span><h2>Recursos del curso</h2><p>Solo materiales relacionados con actividades que requieren entrega digital.</p></div><button className="primary-button" onClick={() => {}}><Icon name="plus" size={14} /> Añadir recurso</button></div><div className="resource-grid">{resources.map((resource) => <button className="resource-card glass-card" key={resource.title} onClick={() => onOpen(resource)}><div className={`resource-preview ${resource.color}`}><span>{resource.icon}</span><small>{resource.type}</small></div><div className="resource-card-body"><h3>{resource.title}</h3><p>{resource.meta} · usado en {resource.used}</p><div><span className="resource-link">Ver actividades relacionadas <Icon name="arrow" size={12} /></span><Icon name="chevron" size={14} /></div></div></button>)}</div></section> }
function ResourceDetail({ resource, onClose }: { resource: typeof resources[number]; onClose: () => void }) { return <div className="drawer-layer" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><aside className="resource-drawer"><div className="drawer-header"><div><span className="eyebrow">RECURSO DEL CURSO</span><h2>{resource.title}</h2><p>{resource.type} · {resource.meta}</p></div><button className="icon-button subtle" onClick={onClose}><Icon name="close" size={17} /></button></div><div className="drawer-body"><div className={`resource-large ${resource.color}`}>{resource.icon}</div><SectionLabel>Usos en actividades</SectionLabel><div className="related-list"><span>La relación con actividades se mostrará desde EduCore Main.</span></div></div><div className="drawer-footer"><button className="ghost-button" onClick={onClose}>Cerrar</button><button className="primary-button">Abrir recurso <Icon name="arrow" size={14} /></button></div></aside></div> }
function ActivityDrawer({ draft, setDraft, onClose, onSave, onPublish }: { draft: Draft; setDraft: React.Dispatch<React.SetStateAction<Draft>>; onClose: () => void; onSave: () => void; onPublish: () => void }) { const [isClosing, setIsClosing] = useState(false); const update = (patch: Partial<Draft>) => setDraft((current) => ({ ...current, ...patch })); const closeModal = () => { if (isClosing) return; setIsClosing(true); window.setTimeout(onClose, 190) }; useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if (event.key === 'Escape') closeModal() }; document.addEventListener('keydown', onKeyDown); return () => document.removeEventListener('keydown', onKeyDown) }, [isClosing]); return <div className="drawer-layer activity-creator-layer" onMouseDown={(e) => e.target === e.currentTarget && closeModal()}><aside className="activity-drawer wide-drawer activity-creator-modal ${isClosing ? 'is-closing' : ''}"><div className="drawer-header"><div><span className="eyebrow">IDEAR · CONFIGURAR · PUBLICAR</span><h2>Nueva actividad</h2><p>Crear un trabajo digital para tus estudiantes.</p></div><button className="icon-button subtle" onClick={closeModal}><Icon name="close" size={17} /></button></div><div className="drawer-body editor-body"><div className="editor-columns"><div><span className="form-section-title">INFORMACIÓN</span><label>Título<input autoFocus value={draft.name} onChange={(e) => update({ name: e.target.value })} placeholder="Ej. actividad de laboratorio" /></label><label>Descripción e instrucciones<div className="rich-editor"><div className="editor-tools"><b>B</b><i>I</i><span>• Lista</span><span>↗ Enlace</span><span>▣ Imagen</span><span>⊞ Tabla</span></div><textarea value={draft.description} onChange={(e) => update({ description: e.target.value })} placeholder="Qué deben crear, analizar o demostrar…" /></div></label><div className="creator-resource-block"><div className="creator-block-heading"><span><Icon name="paperclip" size={15} /> Adjuntar recursos</span><small>Material de apoyo para la entrega</small></div><div className="resource-attach-actions"><button type="button"><Icon name="upload" size={14} /> Subir archivo</button><button type="button"><Icon name="link" size={14} /> Añadir enlace</button></div></div><div className="activity-content-preview"><span className="form-section-title">VISTA PREVIA DEL CONTENIDO</span><strong>{draft.name || 'Título de la actividad'}</strong><p>{draft.description || 'Aquí aparecerán las instrucciones que verá el estudiante.'}</p><small>El estudiante verá esta actividad junto con sus instrucciones y recursos.</small></div><span className="form-section-title">ENTREGA</span><div className="choice-card selected"><span className="choice-radio" /><div><strong>Entrega de archivo</strong><small>El estudiante adjunta uno o varios archivos.</small></div><Icon name="clipboard" size={16} /></div><div className="form-grid"><label>Cantidad máxima<input type="number" min="1" value={draft.maxFiles} onChange={(e) => update({ maxFiles: Number(e.target.value) })} /></label><label>Tamaño por archivo<select value={draft.maxSize} onChange={(e) => update({ maxSize: e.target.value })}><option>10 MB</option><option>25 MB</option><option>50 MB</option><option>100 MB</option></select></label></div><label>Formatos permitidos<div className="format-picker">{fileOptions.map((format) => <button type="button" key={format} className={draft.formats.includes(format) ? 'selected' : ''} onClick={() => update({ formats: draft.formats.includes(format) ? draft.formats.filter((f) => f !== format) : [...draft.formats, format] })}>{format}</button>)}</div></label><span className="creator-subsection-label">Intentos y reenvíos</span><div className="toggle-row"><span>Permitir reemplazo antes de la fecha límite</span><button className={`toggle ${draft.allowReplacement ? 'on' : ''}`} onClick={() => update({ allowReplacement: !draft.allowReplacement })}><i /></button></div><div className="toggle-row"><span>Permitir reenvío</span><button className={`toggle ${draft.allowResubmission ? 'on' : ''}`} onClick={() => update({ allowResubmission: !draft.allowResubmission })}><i /></button></div></div><div><span className="form-section-title">CONFIGURACIÓN</span><span className="creator-subsection-label">Fechas y publicación</span><div className="form-grid"><label>Publicación<input type="date" value={draft.publish} onChange={(e) => update({ publish: e.target.value })} /></label><label>Fecha límite<input type="date" value={draft.due} onChange={(e) => update({ due: e.target.value })} /></label></div><label>Hora<input type="time" defaultValue="23:59" /></label><span className="form-section-title">EVALUACIÓN</span><div className="segmented wide"><button className={draft.graded ? 'active' : ''} onClick={() => update({ graded: true })}>Sí, calificada</button><button className={!draft.graded ? 'active' : ''} onClick={() => update({ graded: false })}>No calificada</button></div>{draft.graded && <><label>Escala<select defaultValue="0.0 – 5.0"><option>0.0 – 5.0</option><option>0 – 100</option><option>Logro cualitativo</option></select></label><div className="choice-card"><span className="rubric-dot" /><div><strong>Rúbrica asociada</strong><small>Criterios configurables · editables después</small></div><span className="violet-text">✓</span></div></>}<span className="form-section-title">GRADE CENTER</span><div className="grade-choice"><div><strong>¿Registrar en Grade Center?</strong><small>{draft.gradeCenter ? 'Esta actividad tendrá un vínculo explícito.' : 'Funciona completamente dentro de ClassCORE.'}</small></div><div className="segmented"><button className={draft.gradeCenter ? 'active' : ''} onClick={() => update({ gradeCenter: true })}>Sí</button><button className={!draft.gradeCenter ? 'active' : ''} onClick={() => update({ gradeCenter: false })}>No</button></div></div>{draft.gradeCenter && <label>Peso opcional<input value={draft.weight} onChange={(e) => update({ weight: e.target.value })} placeholder="Ej. 20%" /></label>}<div className="preview-mini"><span className="eyebrow">RESUMEN DE CONFIGURACIÓN</span><strong>{draft.name || 'Nueva actividad'}</strong><small>Entrega de archivo · {draft.formats.join(', ') || 'sin formatos'}</small><span>{draft.gradeCenter ? `Impacta Grade Center · ${draft.weight || 'sin peso'}` : 'Solo ClassCORE · sin impacto en Grade Center'}</span></div></div></div></div><div className="drawer-footer creator-footer"><span><i className="draft-status-dot" /> Estado inicial: Borrador</span><div><button className="ghost-button" onClick={closeModal}>Cancelar</button><button className="outline-button" onClick={onSave}>Guardar borrador</button><button className="outline-button" onClick={() => document.querySelector('.activity-content-preview')?.scrollIntoView({ behavior: 'smooth', block: 'center' })}><Icon name="eye" size={14} /> Vista previa</button><button className="primary-button" onClick={onPublish}>Publicar actividad <Icon name="arrow" size={13} /></button></div></div></aside></div> }
function StudentPreview({ activity, uploaded, error, sent, onClose, onFile, onSend, onRemove }: { activity: Activity; uploaded: Upload[]; error: string; sent: boolean; onClose: () => void; onFile: (file: File) => void; onSend: () => void; onRemove: (index: number) => void }) { return <div className="drawer-layer" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><aside className="student-preview-drawer"><div className="drawer-header"><div><span className="eyebrow">PREVISUALIZACIÓN · ESTUDIANTE</span><h2>{activity.name}</h2><p>Así verá el estudiante la entrega digital.</p></div><button className="icon-button subtle" onClick={onClose}><Icon name="close" size={17} /></button></div><div className="drawer-body preview-body"><div className="student-instructions"><span className="activity-icon cyan">↗</span><div><strong>Instrucciones</strong><p>{activity.description}</p><small>Fecha límite · {activity.dueDate}</small></div></div><div className="upload-section"><div className="form-section-title">ENTREGA</div>{sent ? <div className="sent-state"><span><Icon name="check" size={22} /></span><strong>Entrega enviada</strong><p>Entrega registrada · {uploaded[0]?.name}</p><StatusPill status="Entregada" /></div> : <><label className="drop-zone"><input type="file" accept={activity.formats.map((f) => `.${f.toLowerCase()}`).join(',')} onChange={(e) => e.target.files?.[0] && onFile(e.target.files[0])} /><span><Icon name="download" size={25} /></span><strong>Arrastra tu archivo aquí</strong><small>o selecciona un archivo · {activity.formats.join(', ')} · máximo {activity.maxSize}</small><b>Seleccionar archivo</b></label>{error && <div className="upload-error">{error}</div>}{uploaded.map((file, index) => <div className="uploaded-file" key={`${file.name}-${index}`}><span className="file-icon"><Icon name="clipboard" size={15} /></span><div><strong>{file.name}</strong><small>{file.format} · {file.size}</small><ProgressBar value={file.progress} /></div><button onClick={() => onRemove(index)}><Icon name="close" size={14} /></button></div>)}<div className="upload-actions"><span>{uploaded.length} / {activity.maxFiles} archivos</span><button className="primary-button" onClick={onSend}>Enviar entrega <Icon name="arrow" size={14} /></button></div></>}</div></div><div className="drawer-footer"><span>Preview funcional · no envía datos reales</span><button className="ghost-button" onClick={onClose}>Cerrar</button></div></aside></div> }

export default App
